import{_ as l,a0 as o,w as u,s as d,I as n,x as a,a1 as i,A as t,ao as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"怎樣在 Ubuntu Linux 中移除 Snap 軟件包 | LCTT x X-CMD","titleTemplate":false,"description":"怎樣在 Ubuntu Linux 中移除 Snap 軟件包 | LCTT (202205) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"怎樣在 Ubuntu Linux 中移除 Snap 軟件包 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"怎樣在 Ubuntu Linux 中移除 Snap 軟件包 | LCTT (202205) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202205/20220428 How to Remove Snap Packages in Ubuntu Linux","title":"怎樣在 Ubuntu Linux 中移除 Snap 軟件包","tag":"202205","desc":""},"relativePath":"202205/20220428 How to Remove Snap Packages in Ubuntu Linux.md","filePath":"[post].md"}'),r={name:"202205/20220428 How to Remove Snap Packages in Ubuntu Linux.md"};function g(b,s,h,k,f,m){const e=o("Link");return u(),d("div",null,[s[26]||(s[26]=n("h1",{id:"怎樣在-ubuntu-linux-中移除-snap-軟件包",tabindex:"-1"},[a("怎樣在 Ubuntu Linux 中移除 Snap 軟件包 "),n("a",{class:"header-anchor",href:"#怎樣在-ubuntu-linux-中移除-snap-軟件包","aria-label":"Permalink to “怎樣在 Ubuntu Linux 中移除 Snap 軟件包”"},"​")],-1)),s[27]||(s[27]=n("p",null,[n("img",{src:"https://img.linux.net.cn/data/attachment/album/202205/09/103449pfqp2yp2rpzgp92l.jpg",alt:""})],-1)),s[28]||(s[28]=n("blockquote",null,[n("p",null,"這是一篇關於在 Ubuntu Linux 系統中如何刪除 Snap，以得到一個無 Snap 系統的教程。")],-1)),s[29]||(s[29]=n("p",null,"由 Canonical 開發的 Snap 軟件包在一些場景下是有益的。它為終端用户直接提供了輕便且快速的程序更新。不僅如此，它還有其他的好處，比如它打包了所有依賴包，並允許安裝同一個應用的多個版本。此外，它運行在沙盒模式，提供了安全和其他方面的好處。",-1)),s[30]||(s[30]=n("p",null,"在這些好處中， Snap 技術也有一些地方備受爭論。舉個例子，幾乎所有使用 Snap 軟件包的用户都説它的性能較差，包括它的啓動時間要比本地 deb 或者 RPM 軟件包時間要長。另外，由於它的設計，程序安裝的體積巨大，浪費磁盤空間，因為它打包了所有用到的依賴包。",-1)),s[31]||(s[31]=n("p",null,"不僅如此，由於沙盒的天然屬性，Snap 程序可能無法訪問你的 Linux 桌面的幾個部分，除非提供了適當的權限。",-1)),s[32]||(s[32]=n("p",null,"這個指南闡述了你如何從 Ubuntu 系統中完全移除 Snap。",-1)),n("p",null,[s[1]||(s[1]=a("這些步驟在 ",-1)),i(e,{href:"https://www.debugpoint.com/2022/01/ubuntu-22-04-lts/"},{default:t(()=>[...s[0]||(s[0]=[a("Ubuntu 22.04 LTS Jammy Jellyfish",-1)])]),_:1}),s[2]||(s[2]=a(" 中進行了測試。然而，它應該也適用於所有的 Ubuntu 系統版本。",-1))]),s[33]||(s[33]=p(`<blockquote><p><strong>警告：這些步驟將會移除 Ubuntu 系統中兩個關鍵的程序：軟件商店和 Firefox。嘗試這些步驟之前確認你已經對書籤和 Firefox 的其它設置做了備份。</strong></p></blockquote><h3 id="在-ubuntu-linux-移除-snap-軟件包" tabindex="-1">在 Ubuntu Linux 移除 Snap 軟件包 <a class="header-anchor" href="#在-ubuntu-linux-移除-snap-軟件包" aria-label="Permalink to “在 Ubuntu Linux 移除 Snap 軟件包”">​</a></h3><p>1、在你的系統中打開一個終端，使用以下命令查看已經安裝的 Snap 軟件包的列表。它顯示了 Snap 軟件包，比如 Firefox，軟件商店，主題以及其它默認已經安裝的核心軟件包。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>snap list</span></span></code></pre></div><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/04/Snap-list-in-Ubuntu.jpg" alt=" Ubuntu Snap 包列表"></p><p>2、按照以下的順序移除 Snap 軟件包。首先移除 Firefox。然後是軟件商店，和用以上命令看到的你的系統中的其它軟件包。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo snap remove --purge firefox</span></span>
<span class="line"><span>sudo snap remove --purge snap-store</span></span>
<span class="line"><span>sudo snap remove --purge gnome-3-38-2004</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo snap remove --purge gtk-common-themes</span></span>
<span class="line"><span>sudo snap remove --purge snapd-desktop-integration</span></span>
<span class="line"><span>sudo snap remove --purge bare</span></span>
<span class="line"><span>sudo snap remove --purge core20</span></span>
<span class="line"><span>sudo snap remove --purge snapd</span></span></code></pre></div><p>3、最後，通過 <code>apt</code> 命令移除 Snap 服務。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt remove --autoremove snapd</span></span></code></pre></div><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/04/remove-snap-and-others-1024x544.jpg" alt="移除 Snap 包和其它"></p><p>這還沒完，即使你用以上命令移除了 Snap 軟件包，但是如果你沒有關閉 apt 觸發器，<code>sudo apt update</code> 命令會再一次將 Snap 安裝回來。</p><p>4、所以，要關閉它，我們需要在 <code>/etc/apt/preferences.d/</code> 目錄下創建一個 apt 設置文件 <code>nosnap.pref</code> 來關閉 Snap 服務。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo gedit /etc/apt/preferences.d/nosnap.pref</span></span></code></pre></div><p>5、添加以下的命令列，並保存該文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Package: snapd</span></span>
<span class="line"><span>Pin: release a=*</span></span>
<span class="line"><span>Pin-Priority: -10</span></span></code></pre></div><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/04/create-a-pref-file.jpg" alt="創建設置文件"></p><p>如果你知道如何使用它，那麼這個 apt 設置文件是一個潛在的工具。舉個例子，在以上的狀態中，<code>Pin-Priority -10</code> 意思就是阻止 Snap 軟件包的安裝。</p>`,18)),n("p",null,[s[4]||(s[4]=a("與這個教程不相關的，舉個例子，如果你想給所有發行版代號為 “bulleye” 的軟件包超高優先權的話，那麼就可以查看這些設置文件。如果你想了解更多，你可以訪問 ",-1)),i(e,{href:"https://manpages.ubuntu.com/manpages/focal/man5/apt_preferences.5.html"},{default:t(()=>[...s[3]||(s[3]=[a("apt 手冊頁",-1)])]),_:1}),s[5]||(s[5]=a("。",-1))]),s[34]||(s[34]=p(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Package: *</span></span>
<span class="line"><span>Pin: release n=bullseye</span></span>
<span class="line"><span>Pin-Priority: 900</span></span></code></pre></div><p>6、回到我們的主題，一旦你已經保存和關閉以上文件，從終端中再次運行以下命令。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt update</span></span></code></pre></div><p>7、最後，從 Ubuntu 中移除 Snap 的步驟全部完成。</p><h3 id="從-ubuntu-移除-snap-後使用-deb-文件安裝軟件商店和-firefox" tabindex="-1">從 Ubuntu 移除 Snap 後使用 deb 文件安裝軟件商店和 Firefox <a class="header-anchor" href="#從-ubuntu-移除-snap-後使用-deb-文件安裝軟件商店和-firefox" aria-label="Permalink to “從 Ubuntu 移除 Snap 後使用 deb 文件安裝軟件商店和 Firefox”">​</a></h3><p>你已經移除了 Firefox 和軟件商店，但是你的工作還需要它們。</p><p>要安裝 apt 版的 GNOME 軟件商店，你可以使用以下命令。確保使用 <code>--install-suggests</code> 參數。否則，將會再次安裝上 Snap 版本的軟件包管理器！</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install --install-suggests gnome-software</span></span></code></pre></div><p>要安裝 Firefox，通過以下命令使用官方 PPA 倉庫。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo add-apt-repository ppa:mozillateam/ppa</span></span>
<span class="line"><span>sudo apt update</span></span>
<span class="line"><span>sudo apt install -t &#39;o=LP-PPA-mozillateam&#39; firefox</span></span></code></pre></div><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/04/Add-the-PPA-1024x550.jpg" alt="添加 PPA 倉庫"></p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/04/Install-Firefox-as-deb-file-from-PPA-1024x548.jpg" alt="從 PPA 倉庫以 deb 文件形式安裝 Firefox"></p>`,12)),n("p",null,[s[7]||(s[7]=a("一旦你已經安裝完 Firefox，使用以下命令開啓自動更新。要了解更多，",-1)),i(e,{href:"https://www.debugpoint.com/2021/09/remove-firefox-snap-ubuntu/"},{default:t(()=>[...s[6]||(s[6]=[a("訪問此頁",-1)])]),_:1}),s[8]||(s[8]=a("。",-1))]),s[35]||(s[35]=p(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>echo &#39;Unattended-Upgrade::Allowed-Origins:: &quot;LP-PPA-mozillateam:\${distro_codename}&quot;;&#39; | sudo tee /etc/apt/apt.conf.d/51unattended-upgrades-firefox</span></span></code></pre></div><p>最後但同樣重要，當運行 <code>apt</code> 時，為 Firefox 創建另一個設置文件給予以上 PPA 倉庫超高優先權。如果你不這麼做，<code>apt update</code> 命令會再次安裝 Snap 版本 Firefox，並把它的“ Snap 朋友們”帶回來 😂😂😂。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo gedit /etc/apt/preferences.d/mozillateamppa</span></span></code></pre></div><p>最後，添加這些命令列並保存文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Package: firefox*</span></span>
<span class="line"><span>Pin: release o=LP-PPA-mozillateam</span></span>
<span class="line"><span>Pin-Priority: 501</span></span></code></pre></div><p>完成。</p><h3 id="在-ubuntu-系統恢復到-snap-軟件包" tabindex="-1">在 Ubuntu 系統恢復到 Snap 軟件包 <a class="header-anchor" href="#在-ubuntu-系統恢復到-snap-軟件包" aria-label="Permalink to “在 Ubuntu 系統恢復到 Snap 軟件包”">​</a></h3><p>如果你改變想法，移除該設置文件，並通過以下命令再次啓動安裝程序。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo rm /etc/apt/preferences.d/nosnap.pref</span></span>
<span class="line"><span>sudo apt update &amp;&amp; sudo apt upgrade</span></span>
<span class="line"><span>sudo snap install snap-store</span></span>
<span class="line"><span>sudo apt install firefox</span></span></code></pre></div><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>關於在 Ubuntu 下移除 Snap 軟件包做個總結，我想説的是這些處理 Snap 軟件包的方法實屬無奈。主要是這對新用户來説很困難。我希望這個指南能幫助你處理好 Snap 軟件包。完結撒花。</p><hr>`,12)),n("p",null,[s[10]||(s[10]=a("via: ",-1)),i(e,{href:"https://www.debugpoint.com/2022/04/remove-snap-ubuntu/"},{default:t(()=>[...s[9]||(s[9]=[a("https://www.debugpoint.com/2022/04/remove-snap-ubuntu/",-1)])]),_:1})]),n("p",null,[s[16]||(s[16]=a("作者：",-1)),i(e,{href:"https://www.debugpoint.com/author/admin1/"},{default:t(()=>[...s[11]||(s[11]=[a("Arindam",-1)])]),_:1}),s[17]||(s[17]=a(" 選題：",-1)),i(e,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[12]||(s[12]=[a("lujun9972",-1)])]),_:1}),s[18]||(s[18]=a(" 譯者：",-1)),i(e,{href:"https://github.com/hwlife"},{default:t(()=>[...s[13]||(s[13]=[a("hwlife",-1)])]),_:1}),s[19]||(s[19]=a(" 校對：",-1)),i(e,{href:"https://github.com/turbokernel"},{default:t(()=>[...s[14]||(s[14]=[a("turbokernel",-1)])]),_:1}),s[20]||(s[20]=a(", ",-1)),i(e,{href:"https://github.com/wxy"},{default:t(()=>[...s[15]||(s[15]=[a("wxy",-1)])]),_:1})]),n("p",null,[s[23]||(s[23]=a("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[21]||(s[21]=[a("LCTT",-1)])]),_:1}),s[24]||(s[24]=a(" 原創編譯，",-1)),i(e,{href:"https://linux.cn/"},{default:t(()=>[...s[22]||(s[22]=[a("Linux中國",-1)])]),_:1}),s[25]||(s[25]=a(" 榮譽推出",-1))])])}const P=l(r,[["render",g]]);export{y as __pageData,P as default};
